<div class="table-wrap"><table><caption>Estudiantes de <?= escape($selectedRoom['name']) ?></caption><thead><tr><th>Estudiante</th><th>Correo</th><th>Entregas</th><th>Calificadas</th></tr></thead><tbody><?php foreach(query("SELECT id,name,email FROM eval_users WHERE role='estudiante' AND group_id=? AND active=1 ORDER BY name",[$selectedGroup])->fetchAll() as $pupil):$deliveries=array_filter($submissions,fn($s)=>(int)$s['student_id']===(int)$pupil['id']&&(!(int)($_GET['activity']??0)||(int)$s['activity_id']===(int)$_GET['activity'])); ?><tr><td><?= escape($pupil['name']) ?></td><td><?= escape($pupil['email']) ?></td><td><?= count($deliveries) ?><?= !$deliveries?' · Sin entrega':'' ?></td><td><?= count(array_filter($deliveries,fn($s)=>$s['grade']!==null)) ?></td></tr><?php endforeach; ?></tbody></table></div>
